<div id="{{ $advanced['id'] }}" class="{{ implode(' ', $rootClasses) }}" style="{{ $rootStyle }}" role="alert" data-entrance-delay="{{ $advanced['entranceDelay'] }}" data-entrance-duration="{{ $advanced['entranceDuration'] }}" @foreach($advanced['attributes'] as $attributeName=>$attributeValue) {{ $attributeName }}="{{ e($attributeValue) }}" @endforeach>
    <div class="pb-alert__body">@if(trim((string) ($settings['title'] ?? '')) !== '')<div class="pb-alert__title" style="{{ $fontStyle('title') }}">{{ (string) $settings['title'] }}</div>@endif @if(trim((string) ($settings['description'] ?? '')) !== '')<div class="pb-alert__description" style="{{ $fontStyle('description') }}">{!! $description !!}</div>@endif</div>
