<script>
(function(){ const bind = () => document.querySelectorAll('[data-pb-alert-dismiss]').forEach((button) => { if (button.dataset.pbAlertReady === '1') return; button.dataset.pbAlertReady = '1'; button.addEventListener('click', () => { const root = button.closest('[role="alert"]'); if (root) root.hidden = true; }); }); if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind, { once:true }); else bind(); })();
</script>
